// --- Merge Sort ---
function mergeSort(arr) {
  if (arr.length <= 1) return arr;           // base case

  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid)); // sort left half
  const right = mergeSort(arr.slice(mid));   // sort right half
  return merge(left, right);                 // combine
}

function merge(left, right) {
  const result = [];
  let i = 0, j = 0;
  // two pointers on two sorted arrays
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) result.push(left[i++]);
    else result.push(right[j++]);
  }
  // append remaining elements
  return result.concat(left.slice(i)).concat(right.slice(j));
}

// --- Dutch National Flag / Quicksort Partition ---
// Rearranges arr[lo..hi] around pivot; returns pivot's final index
function partition(arr, lo, hi) {
  const pivot = arr[hi];
  let i = lo - 1;               // boundary of "less than" region
  for (let j = lo; j < hi; j++) {
    if (arr[j] <= pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]]; // swap into left region
    }
  }
  [arr[i + 1], arr[hi]] = [arr[hi], arr[i + 1]]; // place pivot
  return i + 1;
}

function quickSort(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return;
  const p = partition(arr, lo, hi);
  quickSort(arr, lo, p - 1);
  quickSort(arr, p + 1, hi);
}
